.fm-ch,.fm-ch-popover,.fm-ch-modal-backdrop{--ch-bg:#fff;--ch-border:#e4e7ec;--ch-muted:#667085;--ch-text:#101828;--ch-accent:var(--primary-readable,var(--primary,#d93025));--ch-accent-soft:rgba(var(--primary-rgb,217,48,37),.08);--ch-danger:#d92d20;--ch-hover:#f7f8fa;--ch-sidebar:#f9fafb}
.fm-ch{display:flex;height:100%;min-height:0;background:var(--ch-bg);colour:var(--ch-text);font-size:13.5px;line-height:1.45;border:1px solid var(--ch-border);border-radius:12px;overflow:hidden}
.fm-ch *,.fm-ch-popover *,.fm-ch-modal-backdrop *{box-sizing:border-box}
.fm-ch--embedded{border:none;border-radius:0}
.fm-ch--conversation{border:none;border-radius:0}
.fm-ch--list{border:none;border-radius:0;background:transparent}
.fm-ch--list .fm-ch-sidebar{width:100%;min-width:0;border-right:none;background:transparent;padding:0}
:where(.fm-ch,.fm-ch-popover,.fm-ch-modal-backdrop) button{font:inherit;cursor:pointer;border:none;background:none;colour:inherit;padding:0}
.fm-ch-sidebar{width:240px;min-width:200px;background:var(--ch-sidebar);border-right:1px solid var(--ch-border);display:flex;flex-direction:column;overflow-y:auto;padding:10px 0;flex-shrink:0}
.fm-ch-side-section{padding:8px 10px 2px}
.fm-ch-side-head{display:flex;align-items:centre;gap:2px;padding:2px 8px;colour:var(--ch-muted);font-size:10px;font-weight:950;text-transform:uppercase;letter-spacing:.06em;cursor:pointer}
.fm-ch-side-head button{colour:var(--ch-muted);font-size:11px;line-height:1;padding:4px 7px;border-radius:7px}
.fm-ch-side-head button:hover{background:#eef1f5;colour:var(--ch-accent)}
.fm-ch-side-title{min-width:0;flex:1;text-align:left}
.fm-ch-side-toggle{display:grid;place-items:centre;flex:0 0 auto}
.fm-ch-side-toggle i{width:8px;font-size:8px;transition:transform .16s ease}
.fm-ch-side-section.collapsed .fm-ch-side-toggle i{transform:rotate(-90deg)}
.fm-ch-side-head>.fm-ch-group-badge{margin:0 3px 0 6px}
.fm-ch-group-badge{display:inline-flex;align-items:centre;justify-content:centre;min-width:17px;height:17px;padding:0 5px;border-radius:999px;background:var(--ch-accent);colour:#fff;font-size:9px;font-weight:950;letter-spacing:0}
.fm-ch-side-items[hidden]{display:none}
.fm-ch-side-item{display:flex;align-items:centre;gap:8px;width:100%;text-align:left;padding:5px 10px;border-radius:9px;colour:#344054;min-height:30px;font-size:12px;font-weight:500}
.fm-ch-side-item:hover{background:#eef1f5}
.fm-ch-side-item.active{background:var(--ch-accent-soft);colour:var(--ch-accent);font-weight:650}
.fm-ch-side-item .fm-ch-side-label{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.fm-ch-side-item.unread .fm-ch-side-label{font-weight:750;colour:var(--ch-text)}
.fm-ch-side-item .fm-ch-hash{colour:var(--ch-muted);width:16px;text-align:centre;flex-shrink:0;font-size:11px}
.fm-ch-side-item.active .fm-ch-hash{colour:var(--ch-accent)}
.fm-ch-badge{background:var(--ch-accent);colour:#fff;font-size:10px;font-weight:900;border-radius:999px;min-width:18px;height:18px;display:inline-flex;align-items:centre;justify-content:centre;padding:0 5px;flex-shrink:0}
.fm-ch-main{position:relative;flex:1;display:flex;flex-direction:column;min-width:0;min-height:0}
.fm-ch-header{display:flex;align-items:centre;gap:10px;padding:10px 16px;border-bottom:1px solid var(--ch-border);min-height:52px}
.fm-ch-header-title{font-weight:900;font-size:14.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;display:inline-flex;align-items:centre;gap:8px}
.fm-ch-header-title i{colour:var(--ch-muted);font-size:12px}
.fm-ch-header-topic{colour:var(--ch-muted);font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1;min-width:40px}
.fm-ch-header-actions{display:flex;gap:4px;margin-left:auto;flex-shrink:0}
.fm-ch-tabs{display:flex;align-items:centre;gap:4px;padding:0 14px;border-bottom:1px solid var(--ch-border);min-height:38px;overflow-x:auto}
.fm-ch-tabs[hidden]{display:none}
.fm-ch-tab{align-self:stretch;padding:0 10px!important;border-bottom:2px solid transparent!important;colour:var(--ch-muted)!important;font-size:11.5px!important;font-weight:750!important;white-space:nowrap}
.fm-ch-tab:hover{colour:var(--ch-text)!important}.fm-ch-tab.active{border-bottom-colour:var(--ch-accent)!important;colour:var(--ch-accent)!important}
.fm-ch-quick{padding:4px 10px 8px;display:flex;flex-direction:column;gap:2px}
.fm-ch-resource-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:10px;padding:14px}
.fm-ch-resource{display:flex;align-items:centre;gap:10px;border:1px solid var(--ch-border);border-radius:10px;padding:10px;background:#fff;min-width:0}
.fm-ch-resource-icon{width:36px;height:36px;border-radius:8px;background:var(--ch-accent-soft);colour:var(--ch-accent);display:grid;place-items:centre;flex:0 0 auto}
.fm-ch-resource-copy{min-width:0;flex:1}.fm-ch-resource-copy strong,.fm-ch-resource-copy span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.fm-ch-resource-copy span{font-size:10.5px;colour:var(--ch-muted)}
.fm-ch-workflow-list{display:flex;flex-direction:column;gap:10px}
.fm-ch-workflow-list .fm-ch-resource{width:100%;align-items:flex-start;gap:14px;padding:12px 14px;text-align:left}
.fm-ch-workflow-list .fm-ch-resource:hover{border-colour:#cfd6e1;background:var(--ch-hover)}
.fm-ch-workflow-list .fm-ch-resource:disabled{cursor:default;opacity:.5}
.fm-ch-workflow-list .fm-ch-resource-icon{margin-top:1px}
.fm-ch-workflow-list .fm-ch-resource-copy{text-align:left}
.fm-ch-workflow-list .fm-ch-resource-copy strong{margin-bottom:3px;font-size:13px;font-weight:750;line-height:1.3}
.fm-ch-workflow-list .fm-ch-resource-copy span{font-size:11.5px;line-height:1.45;white-space:normal}
.fm-ch-formatbar{display:flex;align-items:centre;gap:2px;padding-bottom:5px;border-bottom:1px solid #f0f2f5;margin-bottom:5px}.fm-ch-formatbar button{width:26px;height:24px;border-radius:6px;colour:var(--ch-muted)}.fm-ch-formatbar button:hover{background:var(--ch-hover);colour:var(--ch-accent)}
.fm-ch-huddle{position:relative;min-width:0;min-height:0;overflow:auto;background:#111827;colour:#fff;padding:14px;display:flex;flex-direction:column;gap:8px}

.fm-ch-huddle-head,.fm-ch-huddle-actions{display:flex;align-items:centre;gap:8px}
.fm-ch-huddle-head{min-height:20px}.fm-ch-huddle-head strong{flex:1}
.fm-ch-huddle-head>span{font-size:11px;colour:#d0d5dd;white-space:nowrap}
.fm-ch-huddle-head button{width:28px;height:28px;border-radius:8px;colour:#d0d5dd;display:grid;place-items:centre;flex:0 0 auto}.fm-ch-huddle-head button:hover{background:#344054;colour:#fff}
.fm-ch-huddle-recording{display:inline-flex;align-items:centre;gap:5px;colour:#fda29b!important;font-weight:750}.fm-ch-huddle-recording i{font-size:7px;colour:#f04438;animation:fm-ch-rec-pulse 1.4s ease-in-out infinite}
@keyframes fm-ch-rec-pulse{50%{opacity:.35}}
.fm-ch-huddle-actions{margin-top:10px;justify-content:centre}.fm-ch-huddle-actions button{width:36px;height:36px;border-radius:999px;background:#344054;colour:#fff;display:grid;place-items:centre}.fm-ch-huddle-actions button:hover{background:#475467}.fm-ch-huddle-actions button.danger{background:#d92d20}.fm-ch-huddle-actions button:disabled{opacity:.55;cursor:default}
.fm-ch-huddle video{display:block;width:100%;max-height:220px;object-fit:contain;border-radius:9px;background:#000;margin-top:9px}


.fm-ch-huddle-remotes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}.fm-ch-huddle-remotes:empty{display:none}.fm-ch-huddle-remotes video{height:118px;object-fit:cover}
.fm-ch-huddle-roster{display:flex;flex-direction:column;gap:5px;margin-top:9px;padding:8px;border-radius:9px;background:#1d2939}
.fm-ch-huddle-person{display:flex;align-items:centre;gap:8px;min-width:0;font-size:11px;colour:#eaecf0}
.fm-ch-huddle-person .fm-ch-avatar{width:25px;height:25px;font-size:9px}
.fm-ch-huddle-person-name{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:700}
.fm-ch-huddle-person-media{display:flex;gap:7px;colour:#98a2b3;font-size:10px}.fm-ch-huddle-person-media .on{colour:#75e0a7}.fm-ch-huddle-person-media .off{colour:#fda29b}
.fm-ch-huddle-status{display:flex;align-items:centre;gap:7px;margin-top:8px;font-size:10px;colour:#98a2b3}.fm-ch-huddle-status i{font-size:7px;colour:#12b76a}


.fm-ch-huddle [hidden]{display:none!important}

.fm-ch-call-stage{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;flex:1;min-height:160px;overflow:auto}
