.fm-ch-attention-actions{display:flex;align-items:centre;justify-content:flex-end;gap:7px;align-self:centre;min-height:30px}.fm-ch-attention-actions .fm-ch-icon-btn{width:28px;height:28px;border:1px solid #b8c7d9;background:#e2ebf5;colour:#244f78;border-radius:8px}.fm-ch-attention-actions .fm-ch-icon-btn:hover{border-colour:#91a9c2;background:#cfdeed;colour:#153a5b}.fm-ch-attention-dot{width:8px;height:8px;flex:0 0 auto;border-radius:50%;background:#3478a9;box-shadow:0 0 0 2px #fff;transform:translateY(1px)}
.fm-ch-unread-group{border-bottom:1px solid var(--ch-border)}.fm-ch-unread-head{display:flex;align-items:centre;gap:8px;padding:10px 14px;background:#f9fafb;position:sticky;top:47px;z-index:2}.fm-ch-unread-head strong{flex:1;font-size:12px}.fm-ch-unread-count{font-size:10px;colour:var(--ch-muted)}
.fm-ch-thread-card{margin:10px 14px;border:1px solid var(--ch-border);border-radius:11px;overflow:hidden;background:#fff;cursor:pointer}.fm-ch-thread-card:hover{border-colour:#cfd6e1;box-shadow:0 3px 10px rgba(16,24,40,.05)}.fm-ch-thread-card.unread{border-left:3px solid var(--ch-accent)}.fm-ch-thread-card-head{display:flex;align-items:centre;gap:8px;padding:8px 12px;background:#f9fafb;border-bottom:1px solid var(--ch-border);font-size:10.5px;colour:var(--ch-muted)}.fm-ch-thread-card-head strong{colour:var(--ch-text);font-size:11.5px}.fm-ch-thread-card-body{padding:6px 0}.fm-ch-thread-latest{padding:8px 12px;border-top:1px solid #f0f2f5;colour:#344054;font-size:12px}
.fm-ch--compact .fm-ch-msg{padding:2px 12px}
.fm-ch--compact .fm-ch-list{padding:6px 0 2px}
.fm-ch--compact .fm-ch-composer{padding:8px 12px 10px}
.fm-ch--compact .fm-ch-header{min-height:42px;padding:6px 12px}
.fm-ch-mobile-back{display:none;align-items:centre;justify-content:centre;width:34px;height:34px;flex:none;border-radius:9px;colour:var(--ch-muted);font-size:15px}
.fm-ch-mobile-back:hover{background:#eef1f5;colour:var(--ch-accent)}
.fm-ch-header-actions--menu-wrap{position:relative;margin-left:auto}
.fm-ch-header-menu{position:absolute;top:40px;right:0;z-index:40;display:none;flex-direction:column;min-width:224px;background:var(--ch-bg);border:1px solid var(--ch-border);border-radius:12px;box-shadow:0 16px 40px rgba(15,23,42,.16);padding:6px}
.fm-ch-header-menu.open{display:flex}
.fm-ch-header-menu-item{display:flex;align-items:centre;gap:10px;padding:10px 12px;border-radius:9px;font-size:13px;font-weight:650;text-align:left;colour:var(--ch-text)}
.fm-ch-header-menu-item:hover{background:var(--ch-hover)}
.fm-ch-header-menu-item i{width:18px;text-align:centre;colour:var(--ch-muted)}
/* Slack-style mobile navigation for the full workspace: the channel rail and
   the conversation are alternating full-width screens. fm-ch--mobile-list
   shows the rail; selecting anything navigates to the conversation, whose
   header gains a back button. */
@media (max-width:760px){
.fm-ch--full{position:relative;border:none;border-radius:0}
.fm-ch--full .fm-ch-sidebar{position:absolute;inset:0;width:100%;min-width:0;z-index:5;display:none;border-right:none;background:var(--ch-sidebar)}
.fm-ch--full.fm-ch--mobile-list .fm-ch-sidebar{display:flex}
.fm-ch--full .fm-ch-mobile-back{display:inline-flex}
.fm-ch--full .fm-ch-header{padding:10px 12px}
.fm-ch-panel{position:absolute;inset:0;width:100%;min-width:0;z-index:6}
.fm-ch-huddle{min-width:0;width:min(440px,calc(100vw - 20px))}
.fm-ch-popover{max-width:min(360px,calc(100vw - 16px))}
}
